Translate("zhCN", "thousand-needles", {
	title = "千针石林",
	aliases = { "针石林", "千针" },
	sections = {
		{
			title = "概述",
			text = [=[千针石林是{link:the-barrens}贫瘠之地{/link}以南一道巨大的红岩峡谷。它的谷底干燥多尘，从谷底拔起数百座狭长的石柱，又高又细，旅人们便以它们为整片土地命名。{link:tauren}牛头人{/link}经由北缘的{link:the-great-lift}升降梯{/link}进入这里，并从{link:freewind-post}乱风岗{/link}的平顶山上守望着峡谷。在东面，岩石让位于{link:the-shimmering-flats}闪光平原{/link}，一片耀眼的盐原，地精和{link:gnomes}侏儒{/link}在那里驾驶他们自制的机器赛跑。风蛇盘绕在石针之间，双足飞龙在西面的高处筑巢，{link:harpies}鹰身人{/link}在南方的峡谷中尖啸。这是一片美丽的土地，也是一片危险的土地。]=],
		},
		{
			title = "起源",
			text = [=[没有任何编年史记载石针是如何形成如今的模样，也没有记载{link:the-shimmering-flats}闪光平原{/link}何时变成了一片盐漠。{link:tauren}牛头人{/link}在这些峡谷中行走了许多代，{link:centaurs}半人马{/link}在这里追猎他们，就像在{link:kalimdor}卡利姆多{/link}的所有{link:burning-steppes}平原{/link}上追猎他们一样。来到平原的学者们指出，{link:feralas}菲拉斯{/link}的绿色森林与针石林的干燥岩石之间的边界出奇地分明，仿佛是某种古老的魔法划出来的。他们之中没有人能说出那是什么魔法。]=],
		},
		{
			title = "当今",
			text = [=[{link:freewind-post}乱风岗{/link}的{link:tauren}牛头人{/link}控制着峡谷的中心，但除此之外控制的地方很少。加拉克{link:centaurs}半人马{/link}从{link:splithoof-crag}裂蹄峭壁{/link}和{link:camp-e-thok}伊索克营地{/link}出发袭击他们的商队，并发誓要杀死任何胆敢在西面狩猎的牛头人。在{link:darkcloud-pinnacle}黑云峰{/link}上，{link:grimtotem-clan}恐怖图腾氏族{/link}的战士守护着他们死者的墓地，并接待那些秘密往来的陌生人。乱风岗密切监视着他们，一季比一季更不信任他们。

在东面，{link:the-shimmering-flats}闪光平原{/link}已成为一场旷日持久的竞赛的舞台。在{link:mirage-raceway}沙漠赛道{/link}，一支地精车队和一支{link:gnomes}侏儒{/link}车队驾驶火箭车在盐原上竞速，世界上一半的无赖和梦想家都来观看和下注。在赛道以南，{link:explorers-league}探险者协会{/link}的{link:dwarves}矮人{/link}在{link:the-rustmaul-dig-site}锈锤挖掘场{/link}向地下挖掘，而有什么东西从地下挖了回来：一大群巨型昆虫，{link:horde}部落{/link}如今称之为{link:qiraji}异种蝎{/link}。在北缘靠近{link:the-great-lift}升降梯{/link}的地方，{link:quilboar}野猪人{/link}占据着{link:razorfen-downs}剃刀高地{/link}的荆棘巢穴，有人在附近的小径上看到过身穿长袍的邪教徒。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:tauren}牛头人{/link}。{/b} 勇士、猎人和萨满祭司据守着{link:freewind-post}乱风岗{/link}和{link:whitereach-post}白沙岗哨{/link}这处小小的狩猎营地。
• {b}{link:grimtotem-clan}恐怖图腾{/link}。{/b} 一个与众不同的牛头人氏族，据守{link:darkcloud-pinnacle}黑云峰{/link}，不信任其他任何部族。
• {b}加拉克{link:centaurs}半人马{/link}。{/b} 占据{link:splithoof-crag}裂蹄峭壁{/link}和{link:camp-e-thok}伊索克营地{/link}、与牛头人交战的劫掠者。
• {b}{link:mirage-raceway}沙漠赛道{/link}的地精和{link:gnomes}侏儒{/link}。{/b} 机械师、驾驶员、庄家和闲杂人等。
• {b}{link:harpies}鹰身人{/link}。{/b} 尖啸鹰身人在尖啸峡谷和{link:roguefeather-den}飞羽洞穴{/link}中筑巢。
• {b}{link:qiraji}异种蝎{/link}。{/b} 从{link:the-rustmaul-dig-site}锈锤挖掘场{/link}地下蜂拥而出的昆虫。
• {b}野兽。{/b} 风蛇、双足飞龙、美洲狮、土狼、蜥蜴、蝎子以及盐原上的巨龟。]=],
		},
		{
			title = "历史",
			text = [=[• {b}流浪的岁月。{/b} {link:tauren}牛头人{/link}部族在漫长的流浪中穿越这些峡谷，遭到{link:centaurs}半人马{/link}的追猎。{link:freewind-post}乱风岗{/link}的许多牛头人仍记得那些日子。
• {b}夺回莫高雷。{/b} 当{link:cairne-bloodhoof}凯恩·血蹄{/link}在{link:horde}部落{/link}的帮助下带领族人前往{link:mulgore}莫高雷{/link}之后，牛头人变得足够强大，得以重返针石林。没有任何编年史记载他们何时建起了乱风岗和{link:the-great-lift}升降梯{/link}。
• {b}赛车手的到来。{/b} 地精和{link:gnomes}侏儒{/link}发现{link:the-shimmering-flats}闪光平原{/link}是{link:kalimdor}卡利姆多{/link}最平坦的地方，便在上面修建了一条{link:mirage-raceway}赛道{/link}。
• {b}当今。{/b} 加拉克日益猖狂，{link:grimtotem-clan}恐怖图腾{/link}守着秘密，{link:qiraji}异种蝎{/link}已从地下钻了出来。]=],
		},
		{
			title = "针石林的传说",
			text = [=[• {link:whitereach-post}白沙岗哨{/link}的{link:tauren}牛头人{/link}知道一个关于{link:arikara}阿利卡拉{/link}的传说，那是一条复仇之蛇，会从{link:darkcloud-pinnacle}黑云峰{/link}的圣火中升起，向犯下滔天罪行的人复仇。大多数人认为那只是个传说。
• 加拉克守护着一件来自最初的{link:centaurs}半人马{/link}诞生之时的遗物，藏在一团永不熄灭的火焰后面的洞穴里。
• 一头被牛头人称为钢齿的土狼把其他土狼聚集在身边，在峡谷中较温和的野兽之间散播恐惧。
• {link:mirage-raceway}沙漠赛道{/link}的维修人员说，{link:burning-steppes}平原{/link}的每一片土地上都散落着火箭车的残骸，一个细心的拾荒者可以靠它们谋生。]=],
		},
	},
})

Translate("zhCN", "freewind-post", {
	title = "乱风岗",
	aliases = { "乱风" },
	sections = {
		{
			title = "概述",
			text = [=[乱风岗是{link:tauren}牛头人{/link}在{link:thousand-needles}千针石林{/link}的据点，建在峡谷中央的一群平顶山上。绳索和木料搭成的吊桥连接着各座山顶，一部{link:the-great-lift}升降梯{/link}把旅人从谷底载上来。{link:cliffwatcher-longhorn}峭壁卫兵图林·长角{/link}统领着这里的勇士。旅店老板阿比克瓦照看着小屋，莫塔尔保管着各部族的传说，奈瑟的双足飞龙骑手把消息送往{link:thunder-bluff}雷霆崖{/link}和{link:the-crossroads}十字路口{/link}。小屋旁的一根柱子上挂着一张每个勇士都读过的告示：悬赏{link:grimtotem-clan}恐怖图腾{/link}的被逐者{link:arnak-grimtotem}阿纳克{/link}。牛头人从这里的高处可以看到北面的加拉克营地和西北面的恐怖图腾山峰。]=],
		},
	},
})

Translate("zhCN", "the-great-lift", {
	title = "升降梯",
	aliases = { "大升降梯" },
	sections = {
		{
			title = "概述",
			text = [=[升降梯把{link:the-barrens}贫瘠之地{/link}的南缘与下方远处{link:thousand-needles}千针石林{/link}的谷底连接起来。它是{link:tauren}牛头人{/link}建造的，它的平台沿着悬崖用长绳升降。它是从北方进入峡谷唯一便捷的道路，因此有人把守。瑞什·{link:longwalkers}远行者{/link}在这里守望了太久，以至于他把它称为一堆木头，他已经等了好几季，等着有人来换班，好让他去探望家人。卫兵穆赫·月角监视着下方的小径，最近那里{link:centaurs}半人马{/link}的袭击越来越频繁。]=],
		},
	},
})

Translate("zhCN", "whitereach-post", {
	title = "白沙岗哨",
	aliases = { "白沙" },
	sections = {
		{
			title = "概述",
			text = [=[白沙岗哨是峡谷西北部一处小小的{link:tauren}牛头人{/link}营地，位于{link:the-great-lift}升降梯{/link}西南，在通往{link:freewind-post}乱风岗{/link}的路旁。{link:kanati-greycloud}卡纳提·灰云{/link}把它建成了一处狩猎营地，胆敢在加拉克宣称拥有的西部峡谷中狩猎。{link:motega-firemane}莫特加·火鬃{/link}带着年轻的{link:pao-ka-swiftmountain}帕奥卡·迅山{/link}来到这里，研究{link:thousand-needles}针石林{/link}的生物。一个地精工匠{link:wizlo-bearingshiner}维兹罗{/link}在{link:centaurs}半人马{/link}摧毁他的商队之后，在他们之中避难。加拉克打算把营地夷为平地，它那几顶帐篷始终有人看守。]=],
		},
	},
})

Translate("zhCN", "darkcloud-pinnacle", {
	title = "黑云峰",
	sections = {
		{
			title = "概述",
			text = [=[黑云峰是峡谷西北部的一群石针，由{link:grimtotem-clan}恐怖图腾氏族{/link}据守。小径和吊桥在它的尖峰之间攀升，在一座孤立的石针上，恐怖图腾把死者埋葬在一团长久休眠的生命圣火旁。氏族凶猛地守护着这个地方。来历不明的密探曾秘密拜访这里，在恐怖图腾的箱子里留下密封的信件。被逐者{link:arnak-grimtotem}阿纳克{/link}潜伏在附近的悬崖上，他正是把那个被他掳走的{link:tauren}牛头人{/link}女子带到了这里。]=],
		},
	},
})

Translate("zhCN", "splithoof-crag", {
	title = "裂蹄峭壁",
	aliases = { "裂蹄堡" },
	sections = {
		{
			title = "概述",
			text = [=[裂蹄峭壁是加拉克{link:centaurs}半人马{/link}的据点，一个靠着峡谷北壁的兽皮帐篷村落，位于{link:darkcloud-pinnacle}黑云峰{/link}以东、{link:freewind-post}乱风岗{/link}以北。它的劫掠者出发袭击{link:tauren}牛头人{/link}的商队，它的斥候一直活动到乱风岗平顶山的边缘。峭壁的后方是裂蹄堡，一个有人把守的洞穴。在那里，在一个火焰永不熄灭的古老火盆后面，加拉克保管着{link:great-sundering}分裂{/link}之蹄，那是一件来自他们种族诞生之时的遗物。]=],
		},
	},
})

Translate("zhCN", "camp-e-thok", {
	title = "伊索克营地",
	sections = {
		{
			title = "概述",
			text = [=[伊索克营地是加拉克的一处战营，位于{link:thousand-needles}千针石林{/link}的西北角，在{link:the-barrens}贫瘠之地{/link}下方不远处。营地附近散落着一支地精商队的破损马车，{link:centaurs}半人马{/link}袭击并洗劫了这支商队。他们拿走了一切，只留下一头关在笼子里的猎豹，这头野兽凶猛到连半人马都害怕它。猎豹的脖子上仍挂着商队唯一的幸存者{link:wizlo-bearingshiner}维兹罗{/link}的宝贝装置。土狼钢齿和它的狼群在附近的山坡上游荡。]=],
		},
	},
})

Translate("zhCN", "highperch", {
	title = "风巢",
	sections = {
		{
			title = "概述",
			text = [=[风巢是峡谷西缘一处高高的岩架，经由一条沿着崖壁的坡道抵达。它是风巢双足飞龙的筑巢地，它们以野蛮的执着守护着自己的蛋。{link:freewind-post}乱风岗{/link}的{link:tauren}牛头人{/link}在这里收集蛋，为{link:horde}部落{/link}的双足飞龙骑手培育新的坐骑。另一些人则是为了双足飞龙的毒液而来，这种毒液在某些圈子里能卖出高价。一头被猎人们称为剃心的巨大双足飞龙统治着巢穴上方的天空。]=],
		},
	},
})

Translate("zhCN", "roguefeather-den", {
	title = "飞羽洞穴",
	sections = {
		{
			title = "概述",
			text = [=[飞羽洞穴是峡谷南部的一个洞穴，位于{link:freewind-post}乱风岗{/link}以西，在尖啸峡谷的尽头。尖啸{link:harpies}鹰身人{/link}在那里筑巢，在洞穴深处堆积着她们从峡谷中偷来的食物。她们的女族长{link:grenka-bloodscreech}格林卡·血啸{/link}不会在陌生人面前露面，但那些糟蹋鹰身人储藏的人很快就会知道她来得有多快。正因如此，考验年轻人的{link:tauren}牛头人{/link}会把他们送到这里来证明自己的耐力。]=],
		},
	},
})

Translate("zhCN", "windbreak-canyon", {
	title = "风裂峡谷",
	sections = {
		{
			title = "概述",
			text = [=[风裂峡谷沿着{link:freewind-post}乱风岗{/link}与{link:the-shimmering-flats}闪光平原{/link}之间道路的北侧延伸。风蛇在悬崖脚下的巢穴里筑巢，黄昏时分盘绕在石针之上。在其中一个巢穴里，人们发现风蛇守护着一枚不属于它们的蛋。在峡谷附近一处孤零零的{link:razorfen-downs}高地{/link}上，住着考验各部族年轻人的{link:dorn-plainstalker}多恩·平原行者{/link}，在他附近住着为{link:vanishing-of-the-wind-spirits}风之灵{/link}说话的萨满祭司{link:prate-cloudseer}普拉特·白云{/link}。]=],
		},
	},
})

Translate("zhCN", "the-shimmering-flats", {
	title = "闪光平原",
	aliases = { "平原" },
	sections = {
		{
			title = "概述",
			text = [=[闪光平原占据了{link:thousand-needles}千针石林{/link}的东南部：一片白色的盐原，平坦而明亮，上方的空气在热浪中颤抖。覆盖着盐壳的蝎子、蜥蜴、秃鹫和闪闪发光的巨龟生活在这里，它们长得比任何人能解释的都要大。地精和{link:gnomes}侏儒{/link}把{link:burning-steppes}平原{/link}当作他们的赛场，他们引擎的轰鸣在峡谷的崖壁间回荡。在平原的南缘，{link:dwarves}矮人{/link}挖出了{link:the-rustmaul-dig-site}锈锤挖掘场{/link}。在它的北部边界，一支伤痕累累的{link:horde}部落{/link}战斗小队在守望。]=],
		},
	},
})

Translate("zhCN", "mirage-raceway", {
	title = "沙漠赛道",
	aliases = { "赛道" },
	sections = {
		{
			title = "概述",
			text = [=[沙漠赛道是铺设在{link:the-shimmering-flats}闪光平原{/link}上的一条赛道，两支对手车队的维修站分别位于看台的两端。地精用两台引擎和多于理智的火力打造他们的赛车。{link:gnomes}侏儒{/link}在铜栓兄弟的带领下精心打造赛车，却依旧会撞毁。{link:race-master-kronkrider}赛场主管科鲁克莱德{/link}掌管着赛道，播报员高喊赔率，小贩向人群兜售饮料和冰淇淋。喧闹的背后是{link:ginro-hearthkindle}金{/link}钱，有金钱的地方就有阴谋：被盗的图纸、被收买的维修人员，以及有秘密要隐瞒的驾驶员。]=],
		},
	},
})

Translate("zhCN", "the-rustmaul-dig-site", {
	title = "锈锤挖掘场",
	aliases = { "锈锤挖掘点" },
	sections = {
		{
			title = "概述",
			text = [=[锈锤挖掘场位于{link:the-shimmering-flats}闪光平原{/link}的南缘，{link:explorers-league}探险者协会{/link}的一支挖掘队在那里向地下挖掘。{link:horde}部落{/link}派出一支战斗小队去赶走{link:dwarves}矮人{/link}。袭击成功了，但就在战斗中，一大群巨型昆虫从挖掘场内的一个洞穴中冲了出来，一半以上的{link:orcs}兽人{/link}再也没能回家。矮人如今已经离开。昆虫留了下来，数量越来越多：搜寻者、工虫和入侵者，它们的甲壳比部落铁匠所知的任何护甲都要坚固。]=],
		},
	},
})

Translate("zhCN", "cliffwatcher-longhorn", {
